  const output = inspect(value, { colors });
  const lines = output.split("\n").slice(offset, offset + limit);

  return (
    <Box flexDirection="column">
      {lines.map((line, index) => (
        <AnsiText key={offset + index} wrap="none">
          {line || " "}
        </AnsiText>
      ))}
    </Box>
  );
}

